    \end{equation}
    Assuming \eqref{equ:inequality} holds, it follows that
    \[
        {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_s^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 \geq {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 + {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert v_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 \geq {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2.
    \]
    The equality holds if and only if \({\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert v_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert} = 0\), which implies \(v_{s+1}^* = u_{s+1}^* - u_{s}^* = 0\).

    It remains to prove \eqref{equ:inequality}. Suppose, for the sake of contradiction, that \eqref{equ:inequality} does not hold. Define \(v_{s+1}^\eta = (1-\eta)v_{s+1}^* \in \text{span}\Psi_{s+1}\). Then, we have
    \[
        \begin{aligned}
            {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_s^*-v_{s+1}^\eta \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 =& {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s}^*-v_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 + \eta\big(\eta{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert v_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 \\
            &+ 2\langle \mathcal{L}v_{s+1}^*,\mathcal{L}e_{s+1}^*\rangle_{\Omega}+ 2\lambda^2\langle \mathcal{B}v_{s+1}^*,\mathcal{B}e_{s+1}^*\rangle_{\partial\Omega}\big).
        \end{aligned}
    \]
    By choosing \(\eta\) such that
    \[
        0 < \eta < -\frac{2\left(\langle \mathcal{L}v_{s+1}^*, \mathcal{L}e_{s+1}^*\rangle_{\Omega} + \lambda^2\langle \mathcal{B}v_{s+1}^*, \mathcal{B}e_{s+1}^*\rangle_{\partial\Omega}\right)}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert v_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2},
    \]
    we would obtain \({\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_s^* - v_{s+1}^\eta \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2 < {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_s^* - v_{s+1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2\), contradicting the definition of \(v_{s+1}^*\) as the minimizer 
    \begin{equation}
