    \begin{aligned}
        {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \frac{e_{s-1}^*}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} - \frac{\psi_{s}}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \psi_{s} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert} &\leq {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \frac{e_{s-1}^*}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} - \frac{\psi_{s}}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert} + {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \frac{\psi_{s}}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} - \frac{\psi_{s}}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \psi_{s} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}\\
        &=\frac{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^*-\psi_{s} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}} + \frac{\left|{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \psi_{s} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}-{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}\right|}{{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert e_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \psi_{s} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}}\cdot{\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert \psi_{s} \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}
        \leq 2\tau_s.
    \end{aligned}
    \]
    Thus, we have 
    $${\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert u-u_s^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}\leq {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert u-u_{s-1}^* \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert} \cdot \min \left\{1,2 \tau_s\right\}. $$
    Then, the estimate \eqref{equ:converge} follows.

